def transform(grid):
    h, w = len(grid), len(grid[0])
    # Color 3 forms the lattice. Split only on complete separator lines,
    # keeping ordinary constant-background rows/columns inside panels.
    sep_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]

    def bands(n, cuts):
        result = []
        start = 0
        for x in cuts:
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < n:
            result.append((start, n))
        return result

    rb, cb = bands(h, sep_rows), bands(w, sep_cols)
    # Select the panel containing the non-background design, then copy it
    # to every panel of the same dimensions.
    panels = []
    for r0, r1 in rb:
        for c0, c1 in cb:
            tile = [row[c0:c1] for row in grid[r0:r1]]
            panels.append((r0, r1, c0, c1, tile))
    if not panels:
        return [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row if v != 3),
             key=lambda x: sum(row.count(x) for row in grid))
    source = next((p[4] for p in panels if any(v != bg for row in p[4] for v in row)), None)
    if source is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r0, r1, c0, c1, _ in panels:
        if r1-r0 == len(source) and c1-c0 == len(source[0]):
            for dr in range(r1-r0):
                out[r0+dr][c0:c1] = source[dr][:]
    return out

